import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, SkipForward, SkipBack, Volume2, X } from 'lucide-react';
import './Lecteur.css';

function Lecteur({ piste, playlist, onPisteChange, onFermer }) {
  const [enLecture, setEnLecture] = useState(false);
  const [progression, setProgression] = useState(0);
  const [duree, setDuree] = useState(0);
  const [volume, setVolume] = useState(1);
  const audioRef = useRef(null);
  const estMonteRef = useRef(true);

  useEffect(() => {
    estMonteRef.current = true;
    return () => { estMonteRef.current = false; };
  }, []);

  useEffect(() => {
    if (!piste?.url) return;

    // Arrêter l'audio précédent proprement
    const ancienAudio = audioRef.current;
    if (ancienAudio) {
      ancienAudio.pause();
      ancienAudio.src = '';
      ancienAudio.load();
    }

    const audio = new Audio();
    audioRef.current = audio;
    audio.volume = volume;
    setProgression(0);
    setDuree(0);
    setEnLecture(false);

    audio.addEventListener('loadedmetadata', () => {
      if (estMonteRef.current) setDuree(audio.duration);
    });

    audio.addEventListener('timeupdate', () => {
      if (estMonteRef.current) setProgression(audio.currentTime);
    });

    audio.addEventListener('ended', () => {
      if (estMonteRef.current) passerSuivante();
    });

    audio.addEventListener('error', () => {
      if (estMonteRef.current) setEnLecture(false);
    });

    // Charger puis jouer
    audio.src = piste.url;
    audio.load();

    const tentativeLecture = audio.play();
    if (tentativeLecture !== undefined) {
      tentativeLecture
        .then(() => { if (estMonteRef.current) setEnLecture(true); })
        .catch(() => { if (estMonteRef.current) setEnLecture(false); });
    }

    return () => {
      audio.pause();
      audio.src = '';
    };
  }, [piste?.url]);

  const passerSuivante = () => {
    if (!playlist?.length) return;
    const idx = playlist.findIndex(p => p.url === piste.url);
    onPisteChange(playlist[(idx + 1) % playlist.length]);
  };

  const passerPrecedente = () => {
    if (!playlist?.length) return;
    const idx = playlist.findIndex(p => p.url === piste.url);
    onPisteChange(playlist[(idx - 1 + playlist.length) % playlist.length]);
  };

  const toggleLecture = () => {
    if (!audioRef.current) return;
    if (enLecture) {
      audioRef.current.pause();
      setEnLecture(false);
    } else {
      const p = audioRef.current.play();
      if (p !== undefined) {
        p.then(() => setEnLecture(true)).catch(() => {});
      }
    }
  };

  const handleProgression = (e) => {
    const val = parseFloat(e.target.value);
    if (audioRef.current) audioRef.current.currentTime = val;
    setProgression(val);
  };

  const handleVolume = (e) => {
    const val = parseFloat(e.target.value);
    if (audioRef.current) audioRef.current.volume = val;
    setVolume(val);
  };

  const formaterTemps = (s) => {
    if (!s || isNaN(s)) return '0:00';
    const min = Math.floor(s / 60);
    const sec = Math.floor(s % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
  };

  const pourcentage = duree > 0 ? (progression / duree) * 100 : 0;

  if (!piste) return null;

  return (
    <div className="lecteur-global">
      <div className="lecteur-gauche">
        {piste.pochette
          ? <img src={piste.pochette} alt={piste.titre} className="lecteur-pochette" />
          : <div className="lecteur-pochette-defaut">♪</div>
        }
        <div className="lecteur-info">
          <span className="lecteur-titre">{piste.titre}</span>
          <span className="lecteur-artiste">{piste.artiste}</span>
        </div>
      </div>

      <div className="lecteur-centre">
        <div className="lecteur-controles">
          <button className="lecteur-btn" onClick={passerPrecedente}><SkipBack size={20} /></button>
          <button className="lecteur-btn play" onClick={toggleLecture}>
            {enLecture ? <Pause size={24} /> : <Play size={24} />}
          </button>
          <button className="lecteur-btn" onClick={passerSuivante}><SkipForward size={20} /></button>
        </div>
        <div className="lecteur-progression">
          <span className="lecteur-temps">{formaterTemps(progression)}</span>
          <div className="barre-progression-container">
            <div className="barre-progression-remplie" style={{ width: `${pourcentage}%` }} />
            <input type="range" min="0" max={duree || 0} value={progression} onChange={handleProgression} className="barre-progression-input" />
          </div>
          <span className="lecteur-temps">{formaterTemps(duree)}</span>
        </div>
      </div>

      <div className="lecteur-droite">
        <Volume2 size={16} color="#a0aec0" />
        <input type="range" min="0" max="1" step="0.01" value={volume} onChange={handleVolume} className="volume-input" />
        <button className="lecteur-btn-fermer" onClick={() => { audioRef.current?.pause(); onFermer(); }}>
          <X size={18} />
        </button>
      </div>
    </div>
  );
}

export default Lecteur;
